import React from "react";
import styles from './Header.module.css';

function Header() {
    return (
        
        <div className={styles.navigation}>
            <h2>Portfolio</h2>
            <nav>
                <a href="#">Home</a>
                <a href="#">About</a>
                <a href="#">Project</a>
                <a href="#">Skill</a>
                <a href="#">Contact</a>
                <div className={`${styles.animation} ${styles['start-home']}`}></div>
            </nav>
        </div>
    );
}

export default Header;
